/// <summary>
/// One purchase order header for the PO-of-today list. Status is the PurchStatus symbol (Backorder, Received, Invoiced, Canceled, None).
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderSummaryRow
{
    str        purchId;
    str        vendorAccount;
    str        status;
    str        siteId;
    str        warehouseId;
    str        deliveryDate;

}

Method.Source:
[DataMemberAttribute('PurchId')]
public str parmPurchId(str _value = purchId)
{
    purchId = _value;
    return purchId;
}

[DataMemberAttribute('VendorAccount')]
public str parmVendorAccount(str _value = vendorAccount)
{
    vendorAccount = _value;
    return vendorAccount;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('SiteId')]
public str parmSiteId(str _value = siteId)
{
    siteId = _value;
    return siteId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('DeliveryDate')]
public str parmDeliveryDate(str _value = deliveryDate)
{
    deliveryDate = _value;
    return deliveryDate;
}
